function importSheet(text=recipeImportText){recipeImportText=text;modal(`<h2>Add a recipe</h2><form id="recipe-import-form"><label>Paste a recipe<textarea name="recipeText" rows="14" maxlength="50000" required>${esc(text)}</textarea></label><div class="button-row"><label class="button outline">Add photo<input id="recipe-photo" type="file" accept="image/*" capture="environment" hidden></label><button class="primary" type="submit">Import</button></div><p class="photo-tip">A screenshot reads better than a photo of your screen.</p><p class="photo-tip">On iPhone you can select the text in a screenshot and paste it here.</p><p id="ocr-status" class="small muted" aria-live="polite"></p></form>`);}
function basisIngredient(match,basis,item=''){if(basis!=='cooked')return match;const text=(match+' '+item).toLowerCase();if(/soba/.test(text))return ingredients['soba-cooked']?'soba-cooked':match;if(/pasta|noodle/.test(text))return ingredients['pasta-cooked']?'pasta-cooked':match;if(/chickpea|bean|legume/.test(text))return ingredients['chickpea-cooked']?'chickpea-cooked':match;if(/rice/.test(text))return ingredients['rice-cooked']?'rice-cooked':match;return match;}
