function showCrop(file){const current=document.querySelector('#recipe-import-form textarea');if(current)recipeImportText=current.value;pendingRecipePhoto=file;recipeCrop={x:.05,y:.05,w:.9,h:.9};const url=URL.createObjectURL(file);modal(`<h2>Crop recipe text</h2><p>Drag the box over the recipe</p><div class="crop-stage" id="recipe-crop"><img src="${url}" alt="Recipe photo"><div class="crop-box" style="left:5%;top:5%;width:90%;height:90%"><span aria-hidden="true"></span></div></div><div class="button-row">${btn('Read photo','food-recipe-read','','primary')}${btn('Back','food-recipe-back','','outline')}</div>`);const stage=document.querySelector('#recipe-crop'),box=stage.querySelector('.crop-box');let mode='',start=null,initial=null;const move=event=>{if(!start)return;const rect=stage.getBoundingClientRect(),dx=(event.clientX-start.x)/rect.width,dy=(event.clientY-start.y)/rect.height,next={...initial};if(mode==='resize'){next.w=Math.max(.15,Math.min(1-next.x,initial.w+dx));next.h=Math.max(.15,Math.min(1-next.y,initial.h+dy));}else{next.x=Math.max(0,Math.min(1-next.w,initial.x+dx));next.y=Math.max(0,Math.min(1-next.h,initial.y+dy));}recipeCrop=next;Object.assign(box.style,{left:next.x*100+'%',top:next.y*100+'%',width:next.w*100+'%',height:next.h*100+'%'});};box.addEventListener('pointerdown',event=>{mode=event.target.tagName==='SPAN'?'resize':'move';start={x:event.clientX,y:event.clientY};initial={...recipeCrop};box.setPointerCapture(event.pointerId);});box.addEventListener('pointermove',move,{passive:true});box.addEventListener('pointerup',()=>{start=null;},{passive:true});box.addEventListener('pointercancel',()=>{start=null;},{passive:true});document.querySelector('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
