 if(f.id==='custom-recipe-form'){captureRecipe();const r=recipeDraft;if(!r.name.trim()||!r.rows.length)throw Error('Add a name and at least one ingredient');const items={};for(const row of r.rows){if(!ingredients[row.id]||row.grams<=0)throw Error('Choose ingredients and positive amounts');items[row.id]=(items[row.id]||0)+row.grams/r.servings;}const record=stamp({id:r.id||uid(),name:r.name.trim(),items,servings:r.servings,time:r.time,prep:r.time,cook:0,mealType:r.mealType,tag:'My recipe',gear:r.gear,steps:r.steps.trim()?r.steps.trim().split('\n'):['Prepare and combine the ingredients'],subs:'',storage:''});F.validateFoodExtension({customRecipes:[record]});if(save('Saved',()=>{s().customRecipes=s().customRecipes.filter(x=>x.id!==record.id);s().customRecipes.push(record);}))close();return true;}
